typeSystemExample.source:
#include <iostream>

template <typename T>
T max_of(T a, T b) {
    return a >= b ? a : b;
}

int main() {
    std::cout << max_of(3, 7) << '\n';
    std::cout << max_of(1.5, 2.8) << '\n';
}

concurrencyExample.source:
#include <iostream>
#include <thread>
#include <vector>

int main() {
    int results[4];
    std::vector<std::thread> threads;
    for (int i = 0; i < 4; i++)
        threads.emplace_back([&results, i] { results[i] = i * i; });
    for (auto& t : threads) t.join();
    for (int r : results) std::cout << r << ' ';
}
